cypress_script:
describe('Floating Navigation Menu Links', () => {
  it('should navigate to Home, News, Contact, and About without changing the URL', () => {
    cy.visit('https://the-internet.herokuapp.com/floating_menu');
    cy.get('a[href="#home"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/floating_menu');
    cy.get('a[href="#news"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/floating_menu');
    cy.get('a[href="#contact"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/floating_menu');
    cy.get('a[href="#about"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/floating_menu');
  });

  it('should navigate to Elemental Selenium and change the URL', () => {
    cy.visit('https://the-internet.herokuapp.com/floating_menu');
    cy.get('a[href="http://elementalselenium.com/"]').click();
    cy.url().should('eq', 'http://elementalselenium.com/');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Floating Navigation Menu Links', () => {
  test('should navigate to Home, News, Contact, and About without changing the URL', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a[href="#home"]');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a[href="#news"]');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a[href="#contact"]');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a[href="#about"]');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/floating_menu');
  });

  test('should navigate to Elemental Selenium and change the URL', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a[href="http://elementalselenium.com/"]');
    expect(page.url()).toBe('http://elementalselenium.com/');
  });
});
